Describe 'Remove-DistroNexusInstance lifecycle facade' -Tag 'Unit', 'Public', 'Lifecycle' {
    BeforeAll { Import-Module (Join-Path $PSScriptRoot '..\..\..\..\src\PowerShell\DistroNexus.psd1') -Force }
    It 'uses reviewed remove routes without tag or schedule cleanup' { InModuleScope DistroNexus { Mock Invoke-DistroNexusWorkspaceBridge { if ($Operation -like '*.preview.v1') { [pscustomobject]@{ PreviewToken=('c'*64) } } else { [pscustomobject]@{ Succeeded=$true } } }; Mock Remove-DistroNexusBackupSchedule {}; Remove-DistroNexusInstance -Name Ubuntu -Confirm:$false | Out-Null; Should -Invoke Invoke-DistroNexusWorkspaceBridge -ParameterFilter { $Operation -eq 'instance.remove.preview.v1' } -Times 1; Should -Invoke Invoke-DistroNexusWorkspaceBridge -ParameterFilter { $Operation -eq 'instance.remove.execute.v1' -and $Payload.Keys.Count -eq 1 } -Times 1; Should -Invoke Remove-DistroNexusBackupSchedule -Times 0 } }
}
